+import { Worker, isMainThread } from 'worker_threads';
+
+let activeJobCount = 0;
+const jobQueue: Job[] = [];
+
+export function enqueueJob(job: Job) {
+  jobQueue.push(job);
+  activeJobCount++;
+  processNext();
+}
+
+function processNext() {
+  if (jobQueue.length === 0) return;
+  const job = jobQueue.shift()!;
