+const DEFAULT_TIMEOUT_MS = 5000;
+const MAX_RETRIES = 3;

 export async function request(url: string, opts: RequestOpts = {}) {
-  return axios({ url, timeout: DEFAULT_TIMEOUT_MS, ...opts });
+  let lastErr;
+  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
